// ---------------------------------------------------------------------------
// CHECKEXPR IMPLEMENTATION --------------------------------------------------

def checkExprOperators(expr: Expr, expected: Option[Type]): Expr = expr match {

  // For a tight juxt, create a MathPrimary
  case SJuxt(info, multi, infix, front::rest, false, true) => {
    def toMathItem(exp: Expr): MathItem = {
      val span = NU.getSpan(exp)
      if ( exp.isInstanceOf[TupleExpr] ||
           exp.isInstanceOf[VoidLiteralExpr] ||
           NU.isParenthesized(exp) )
        EF.makeParenthesisDelimitedMI(span, exp)
      else EF.makeNonParenthesisDelimitedMI(span, exp)
    }
    checkExpr(SMathPrimary(info, multi, infix, front, rest.map(toMathItem)), expected)
  }

  // If this juxt is actually a fn app, then rewrite to a fn app.
  case SJuxt(info, multi, infix, front::rest, true, true) => rest.length match {
    case 1 => checkExpr(S_RewriteFnApp(info, front, rest.head), expected)
    case n => // Make sure it is just two exprs.
      signal(expr, errorMsg("TightJuxt denoted as function application but has ",
                            int2Integer(n), "(!= 2) expressions."))
      expr
  }

  /* Loose Juxts are handled using the algorithm in 16.8 of Fortress Spec 1.0
   * ToDo: Revisit
   */
  case SJuxt(SExprInfo(span,paren,optType),
             multi, infix, exprs, isApp, false) => {
    // Check subexpressions
    //val checkedExprs = exprs.map(checkExprIfCheckable).map(_.fold(x=>x,x=>x))
    //if (!haveTypesOrUncheckable(checkedExprs)) { return expr }
    val checkedExprs = exprs.map(checkExpr)
    if(!haveTypes(checkedExprs)) {return expr}
    // Break the list of expressions into chunks.
    // First the loose juxtaposition is broken into nonempty chunks;
    // wherever there is a non-function element followed
    // by a function element, the latter begins a new chunk.
    // Thus a chunk consists of some number (possibly zero) of
    // functions followed by some number (possibly zero) of non-functions.
    def chunker(exprs: List[Expr], results: List[(List[Expr],List[Expr])]): List[(List[Expr],List[Expr])] = exprs match {
      case Nil => results.reverse
      case first::rest =>
        if ( isArrows(first) ) {
          val (arrows,temp) = (first::rest).span(isArrows)
          val (nonArrows,remainingChunks) = temp.span((e:Expr) => !isArrows(e))
          chunker(remainingChunks, (arrows,nonArrows)::results)
        } else {
          val (nonArrows,remainingChunks) = (first::rest).span((e:Expr) => !isArrows(e))
          chunker(remainingChunks, (List(),nonArrows)::results)
        }
    }
    val chunks = chunker(checkedExprs, List())
    // Left associate nonarrows as a single OpExpr
    def associateNonArrows(nonArrows: List[Expr]): Option[Expr] =
      nonArrows match {
        case Nil => None
        case head::tail =>
          Some(tail.foldLeft(head){ (e1: Expr, e2: Expr) =>
                                    EF.makeOpExpr(infix,e1,e2) })
      }
    // Right associate everything in a chunk as a _RewriteFnApp
    def associateArrows(fs: List[Expr], oe: Option[Expr]) = oe match {
      case None => fs match {
        case Nil =>
          errors.signal("Empty chunk", expr)
          expr
        case _ =>
          fs.take(fs.size-1).foldRight(fs.last){ (f: Expr, e: Expr) =>
                                                 EF.make_RewriteFnApp(f,e) }
      }
      case Some(e) =>
        fs.foldRight(e){ (f: Expr, e: Expr) => EF.make_RewriteFnApp(f,e) }
    }
    // Associate a chunk
    def associateChunk(chunk: (List[Expr],List[Expr])): Expr = {
      val (arrows, nonArrows) = chunk
      associateArrows(arrows, associateNonArrows(nonArrows))
    }
    val associatedChunks = chunks.map(associateChunk)
    // (1) If any element that remains has type String,
    //     then it is a static error
    //     if there is any pair of adjacent elements within the juxtaposition
    //     such that neither element is of type String.
    val types = if ( haveTypes(associatedChunks) )
                  associatedChunks.map((e: Expr) => getType(e).get)
                else List()
    def isStringType(t: Type) = isTrue(analyzer.subtype(t, Types.STRING))
    if ( types.exists(isStringType) ) {
      def stringCheck(e: Type, f: Type) =
        if ( ! (isStringType(e) || isStringType(f)) ) {
          signal(expr, errorMsg("Neither element is of type String in ",
                                "a juxtaposition of String elements."))
          e
        } else e
      types.take(types.size-1).foldRight(types.last)(stringCheck)
    }
    // (2) Treat the sequence that remains as a multifix application
    //     of the juxtaposition operator.
    //     The rules for multifix operators then apply.
    //     Either way the application is the juxtaposition's value, so it
    //     has the juxtaposition's expected type.
    val multiOpExpr =
      STypeCheckerFactory.makeTryChecker(this).
        tryCheckExpr(EF.makeOpExpr(span,
                                   paren,
                                   toJavaOption(optType),
                                   multi,
                                   toJavaList(associatedChunks)),
                     expected)
    multiOpExpr.getOrElse {
      // If not, left associate as InfixJuxts
      associatedChunks match {
        case Nil =>
          errors.signal("Empty juxt", expr)
          expr
        case head::tail =>
          checkExpr(tail.foldLeft(head){ (e1: Expr, e2: Expr) =>
                                         EF.makeOpExpr(infix,e1,e2) },
                    expected)
      }
    }
  }

  // Math primary, which is the more general case,
  // is going to be called for both tight Juxt and MathPrimary

  // Base case of recursion: If there is no 'rest', return the Expr
  case SMathPrimary(info, multi, infix, front, Nil) => checkExpr(front, expected)

  case mp@SMathPrimary(info@SExprInfo(span,paren,optType),
                       multi, infix, front, rest@second::remained) => {
    /** Check for ^ followed by ^ or ^ followed by [], both static errors. */
    def exponentiationStaticCheck(items: List[MathItem]) = {
      var exponent: Option[MathItem] = None
      def checkMathItem(item: MathItem) = item match {
        case SExponentiationMI(_,_,_) => exponent match {
          case None => exponent = Some(item)
          case Some(e) => syntaxError(item, "Two consecutive ^s.")
        }
        case SSubscriptingMI(_,_,_,_) => exponent match {
          case Some(e) =>
            syntaxError(item, "Exponentiation followed by subscripting is illegal.")

        // Not happy about passing null for defaultApi, but don't think it is necessary for schema normalization
        val modifiedSchema = Some(new FnNameInfo(declaredMethod, null).normalizedSchema(overloadingSchema.get));

        val res : MethodInvocation =
          SMethodInvocation(info, selfRef, origName, staticArgs, bestArg,
                  overloadingType, modifiedSchema)
                  // System.err.println(span+": app of "+checkedFn+
                  //                    "\n  selfType="+selfType+
                  //                    "\n  self: "+getType(selfRef)+
                  //                    "\n  REWRITTEN TO: "+res.toStringReadable())
                  res
      case _ =>
          S_RewriteFnApp(info, newFn, bestArg)
      }
    }

    case app @ SOpExpr(SExprInfo(span, paren, _), op, args) => {
      val checkedOp = checkExpr(op).asInstanceOf[FunctionalRef]
      val preCandidates = getCandidatesForFunction(checkedOp, expr).getOrElse(return expr)
      val opName = checkedOp.getOriginalName.asInstanceOf[Op]
      implicit val errorFactory = new ApplicationErrorFactory(expr, None, preCandidates.length > 1)

      // Type check the application.
      val (candidates, callType) = typedApplication(preCandidates, args, expected, Some(opName), false).
                         getOrElse(return expr)
      val AppCandidate(bestArrow, bestSargs, bestArgs, _, _) = candidates.head

      // Rewrite the applicand to include the arrow and static args
      // and update the application.
      val newOp = rewriteApplicand(checkedOp, candidates, false).asInstanceOf[FunctionalRef]
      SOpExpr(SExprInfo(span, paren, Some(callType)), newOp, bestArgs)
    }

    case SFnExpr(SExprInfo(span, paren, _),
                 SFnHeader(a, b, c, d, e, f, tempParams, declaredRetType), body) => {
      // If expecting an arrow type, use its domain to infer param types.
      val (params, expectedRetType) = expected match {
        case Some(arrow:ArrowType) =>
          (addParamTypes(arrow.getDomain, tempParams).getOrElse(tempParams), Some(arrow.getRange))
        case _ => (tempParams, None)
      }
                checkExpr(EF.makeOpExpr(NU.spanTwo(r, e), infix, r, e))
              }
            }
          }
      }
    }

    // First try to type check this expression as a multifix operator expression.
    // If that fails, type check it as some number of applications of the infix
    // operator, left associatively.
    case SAmbiguousMultifixOpExpr(info, infixOp, multifixOp, args) => {
      def infixAssociate(e1: Expr, e2: Expr) = SOpExpr(info, infixOp, List(e1, e2))
      STypeCheckerFactory.makeTryChecker(this).
        tryCheckExpr(SOpExpr(info, multifixOp, args)).
        getOrElse(checkExpr(args.reduceLeft(infixAssociate)))
    }

    // For a SChainExpr, we must do these steps:
    // (1) Check each subexpression.
    // (2) Check each operator application (using dummy expressions as operands).
    // (3) Check the nested applications of the andOp operator (using dummy expressions as operands).
    // (4) Assemble all the pieces into a new SChainExpr.
    case SChainExpr(SExprInfo(span,parenthesized,_), first, links) => {
      bug("ChainExpr should have been desugared before type checking")
//       val checkedFirst = checkExpr(first)
//       val checkedLinkExprs = links.map(ln => checkExpr(ln.getExpr))
//       val checkedLinkDummies = checkedLinkExprs.map(e => makeDummyFor(e))

//       // Build up a list of OpExprs from the Links (in reverse).
//       def makeOpExpr(prevAndResult: (Expr, List[OpExpr]),
//                      nextStuff: (Expr, FunctionalRef))

          /* get types of all fields of the type "ty" corresponding to each pattern."*/
          val collected = ps.zipWithIndex.map(pbToPbTy(_, ty)).map(getBoundIdWithType)
          (normalize(NF.makeIntersectionType(ty, expr_type)),
           collected.foldRight(List[(Id,Type)]()){ (pair, idty_list) => pair._2 ::: idty_list})

        case None => // tuple pattern
          if ((ps.length != expr_size) || !isTupleType) {
            signal(tp, "The typecase clause, " + pattern + ", is unreachable.")
            (expr_type, List())
          } else {
            val eltTypes = toList(expr_type.asInstanceOf[TupleType].getElements)
            val collected = (ps zip eltTypes).map(getBoundIdWithType)
            (normalize(NF.makeMaybeTupleType(NU.getSpan(tp), toJavaList(collected.map(_._1)))),
             collected.foldRight(List[(Id,Type)]()){ (pair, idty_list) => pair._2 ::: idty_list})
          }
      }
    } else {
        val ty = tp.asInstanceOf[Type]
        (normalize(NF.makeIntersectionType(ty, expr_type)), List())
      }
  }

  // Check each typecase clause:
  //   Collect pattern variables and their types using checkedType
  //   Extend the typechecker with the new id/type information
  //   Type-check the body of the typecase clause
  def checkClause(c: TypecaseClause, checkedType: Type, expected: Option[Type]): TypecaseClause = {
    val STypecaseClause(info, nameOpt, matchType, body) = c
    // Construct the types corresponding to ids
    val checkLeft = getTypeAndIdTyList(matchType, checkedType)
    // Redundancy check : signals an error if a type in a type clause exclusives the type of the selector 

    if (self.analyzer.excludes (checkedType, checkLeft._1)==True){
      signal (checkLeft._1, "The typecase clause, " + matchType + ", is unreachable.")
    } 
    var idty_list : List[(Id, Type)] = checkLeft._2
    idty_list = if (nameOpt.isDefined) (nameOpt.get, checkLeft._1) :: idty_list
                else idty_list
    //idty_list.foreach(pair => System.out.println(pair._1 +", " + pair._2))
    val newChecker = this.extend(idty_list)
    val checkedBody = newChecker.checkExpr(body, expected).asInstanceOf[Block]
    STypecaseClause(info, nameOpt, matchType, checkedBody)
  }

  def checkExprMisc(expr: Expr, expected: Option[Type]): Expr = expr match {

----
                      selfType)
        case _ => signal(o, errorMsg("Self type is not inferred for ", o)); o
      }
    }

    /* Matches if block is an atomic block. */
    case SBlock(SExprInfo(span,parenthesized,resultType),
                loc, true, withinDo, exprs) =>
      /* Strip the "atomic" to avoid infinite recursion;
       * then set it back again */
      NF.remakeAtomic(
      forAtomic(SBlock(SExprInfo(span,parenthesized,resultType),
                       loc, false, withinDo, exprs),
                "an 'atomic' do block").asInstanceOf[Block])

    /* Matches if block is not an atomic block. */
    case SBlock(SExprInfo(span,parenthesized,resultType),
                loc, false, withinDo, exprs) => {
      val newLoc = loc match {
        case Some(l) =>
          Some(checkExpr(l, Types.REGION, errorString("Location of the block")))
        case None => loc
      }
      exprs.reverse match {
        case Nil =>
          SBlock(SExprInfo(span,parenthesized,Some(Types.VOID)),
                 newLoc, false, withinDo, exprs)
        case last::rest =>
          val allButLast = rest.map((e: Expr) => checkExpr(e, Types.VOID,
                                                           errorString("Non-last expression in a block")))
          val lastExpr = checkExpr(last, expected)
          val newExprs = (lastExpr::allButLast).reverse
          SBlock(SExprInfo(span,parenthesized,getType(lastExpr)),
                 newLoc, false, withinDo, newExprs)
